const MOD = 1000000007;

function solve() {
    const input = require('fs').readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;
    const n = parseInt(input[0], 10);
    const k = parseInt(input[1], 10);

    if (k > n) {
        console.log(0);
        return;
    }

    // pow2[i] = 2^i % MOD
    const pow2 = new Array(n + 1);
    pow2[0] = 1;
    for (let i = 1; i <= n; i++) {
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }

    // Precompute geometric sums: geo[s][len] = sum_{i=0}^{len-1} s^i mod MOD
    // where s = pow2[x] for some x.
    // We need geo[pow2[x]][len] for x=1..n, len=1..n.
    // geo[s][0] = 0.
    const geo = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
    for (let x = 1; x <= n; x++) {
        const s = pow2[x];
        geo[x][0] = 0;
        for (let len = 1; len <= n; len++) {
            geo[x][len] = (geo[x][len - 1] * s + 1) % MOD;
        }
    }

    // dp[i][j] = number of ways for prefix [1..i] with max independent set size = j
    const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0));
    dp[0][0] = 1;

    for (let i = 1; i <= n; i++) {
        // Contribution from Case 1: point i is not covered by any chosen interval
        // This adds (2^i - 1) subsets of intervals ending at i (that are not chosen in MIS)
        // multiplied by dp[i-1][j].
        const ways1 = (pow2[i] - 1 + MOD) % MOD;
        for (let j = 0; j <= k; j++) {
            dp[i][j] = (dp[i][j] + dp[i - 1][j] * ways1) % MOD;
        }

        // Contribution from Case 2: point i is the right endpoint of the last interval in MIS
        // Iterate over previous right endpoint p (0 <= p < i).
        // x = i - p is the length of the gap + 1.
        // The last interval is [l, i] where l in [p+1, i].
        // Sum over l of 2^{i-l} = sum_{d=0}^{x-1} 2^d = geo[1][x].
        // Intervals strictly inside (p, i) not touching i: count geo[2][x-1].
        for (let p = 0; p < i; p++) {
            const x = i - p;
            // sum_{l=p+1}^{i} 2^{i-l} = sum_{d=0}^{x-1} 2^d
            const waysLast = geo[1][x];
            // intervals strictly inside (p, i)
            const waysMid = geo[2][x - 1]; // Note: geo[2][0] = 0 handled by initialization

            // We transition from dp[p][j-1] to dp[i][j]
            // Total ways for this p, x: waysLast * waysMid
            const transWays = (waysLast * waysMid) % MOD;

            for (let j = 1; j <= k; j++) {
                dp[i][j] = (dp[i][j] + dp[p][j - 1] * transWays) % MOD;
            }
        }
    }

    console.log(dp[n][k] % MOD);
}

solve();
